xyr <- cbind(x, y, r)
xaxis <- sort(unique(xyr[, 1]))
yaxis <- sort(unique(xyr[, 2]))
z <- matrix(xyr[, 3], length(xaxis), length(yaxis), byrow)
padx <- abs(diff(xaxis))[1]
pady <- abs(diff(yaxis))[1]
plot(mean(xaxis), mean(yaxis), type='n', xlim = c(min(xaxis) - padx, max(xaxis) + padx), ylim = c(min(yaxis) - pady, max(yaxis) + pady), xlab = 'time', ylab = 'lat_range_z_trans', xaxt = 'n')
