xtk_lbl <- abs(xtk_lbl)
axis(side = 1, at = xtk, labels = xtk_lbl)
image.plot(xaxis, yaxis, z[zreord, ], add = TRUE, col = col)
contour(xaxis, yaxis, z[zreord, ], col = 'grey50', add = TRUE)
